def getHappyString(n, k):
    def generate_happy_strings(n):
        def backtrack(current, length):
            if length == n:
                yield current
                return
            for char in ['a', 'b', 'c']:
                if not current or current[-1] != char:
                    yield from backtrack(current + char, length + 1)

        yield from backtrack('', 0)

    happy_strings = list(generate_happy_strings(n))
    if k > len(happy_strings):
        return ""
    return happy_strings[k - 1]
